import json, hashlib, os, subprocess, sys
from pathlib import Path

source=Path("/Users/steventran/do-again")
projects=[
  source,
  Path("/Users/steventran/jobpipe"),
  Path("/Users/steventran/Sonary"),
]

sys.path.insert(0,str(source/"src"))
from do_again.service.rollout import _tree_hash

def run(cwd,args,env=None):
    return subprocess.run(args,cwd=cwd,text=True,capture_output=True,check=False,env=env)

def read_json(p):
    try:
        v=json.loads(p.read_text())
        return v if isinstance(v,dict) else {}
    except Exception:
        return {}

source_head=run(source,["git","rev-parse","HEAD"]).stdout.strip()
source_hash=_tree_hash(source/"src/do_again")
rows=[]

for repo in projects:
    key=hashlib.sha256(str(repo.resolve()).encode()).hexdigest()[:12]
    root=Path.home()/".do_again/projects"/key
    runtime=root/"runtime/do_again"
    state=root/"state"
    cfg=(repo/"do-again.toml").read_text() if (repo/"do-again.toml").is_file() else ""
    status=run(source,["python3","-m","do_again.cli","status",str(repo)],env={**os.environ,"PYTHONPATH":str(source/"src")})
    outbox=list((state/"browser_outbox").glob("*.json")) if (state/"browser_outbox").is_dir() else []
    rows.append({
      "repo":str(repo),
      "runtime_hash":_tree_hash(runtime),
      "runtime_matches_source":_tree_hash(runtime)==source_hash,
      "continuous": "continuous = true" in cfg.lower(),
      "report_stalls": "report_stalls = true" in cfg.lower(),
      "status_rc":status.returncode,
      "status_stdout":status.stdout,
      "browser_status":read_json(state/"browser_status.json"),
      "liveness":read_json(state/"liveness.json"),
      "outbox_count":len(outbox),
      "uncertain_delivery_exists":(state/"browser_delivery_uncertain.json").is_file(),
    })

print(json.dumps({
  "source_head":source_head,
  "source_hash":source_hash,
  "projects":rows,
  "evidence":{
    "criterion_1_safe_upgrade":"staged upgrade deferral + verified rollout journals + stale-start blocked_ambiguous_replay recovery",
    "criterion_2_intentional_continuous":"continuous=true verified across all three configs",
    "criterion_3_status_lifecycle":"do-again status exposes liveness_state and browser delivery state across all three",
    "criterion_4_fault_matrix":"live/installed proofs -104, -117, -118, -119, -121 plus Sonary stale-start recovery -128",
    "criterion_5_incident_notification":"#19/#20 race reproduced, PR #22 fix merged, #30 live dedupe proof passed; local state persisted",
    "criterion_6_runtime_validation":"canonical runtime parity + ready browser/outbox state checked below",
  }
},indent=2,sort_keys=True))

for row in rows:
    if not row["runtime_matches_source"]:
        raise SystemExit(f"runtime mismatch: {row['repo']}")
    if not row["continuous"]:
        raise SystemExit(f"continuous disabled: {row['repo']}")
    if "liveness_state=" not in row["status_stdout"]:
        raise SystemExit(f"status missing liveness_state: {row['repo']}")
    if row["outbox_count"] != 0:
        raise SystemExit(f"outbox not empty: {row['repo']} count={row['outbox_count']}")
    if row["uncertain_delivery_exists"]:
        raise SystemExit(f"uncertain delivery remains: {row['repo']}")

print("ISSUE10_FINAL_CLOSURE_AUDIT_OK")
